mapper.select:
SELECT ae.id, ae.event_no, ae.source_device_id, ae.water_area_id, ae.confidence, ae.alert_type, ae.status, ae.snapshot_url, ae.video_clip_url, ae.confirmed_by, ae.confirmed_at, ae.false_alarm_reason, ae.resolved_at, ae.created_at, ae.updated_at, ae.deleted, ae.alert_location, d.device_name AS source_device_name, w.name AS water_area_name, u.real_name AS confirmed_by_name FROM alert_event ae LEFT JOIN device d ON ae.source_device_id = d.id LEFT JOIN water_area w ON ae.water_area_id = w.id LEFT JOIN sys_user u ON ae.confirmed_by = u.id WHERE ae.deleted = 0
AND ae.status = #{status}
AND ae.water_area_id = #{waterAreaId}
AND ae.alert_type = #{alertType}
ORDER BY ae.created_at DESC

mapper.update:
UPDATE alert_event
event_no = #{event.eventNo}, source_device_id = #{event.sourceDeviceId}, water_area_id = #{event.waterAreaId}, alert_location = #{event.alertLocation}, confidence = #{event.confidence}, alert_type = #{event.alertType}, status = #{event.status}, snapshot_url = #{event.snapshotUrl}, video_clip_url = #{event.videoClipUrl}, confirmed_by = #{event.confirmedBy}, confirmed_at = #{event.confirmedAt}, false_alarm_reason = #{event.falseAlarmReason}, resolved_at = #{event.resolvedAt}, updated_at = NOW()
WHERE id = #{event.id}
